import axios from "axios";

// Replace with your backend server URL
const API = axios.create({ baseURL: "http://localhost:3001" });

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = localStorage.getItem("token");
    if (token) {
        req.headers.Authorization = `Bearer ${token}`;
    }
    return req;
});

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        const response = await API.post('/login', { username, password });
        return response.data; // Assuming response contains: { token, user }
    } catch (error) {
        console.error("Login failed:", error.response?.data || error.message);
        throw error; // Rethrow the error so it can be handled in components
    }
};

// Franchise APIs
export const AddExamCenter = async (data) => {
    try {
        const response = await API.post("/franchises", data);
        return response.data; // Assuming response contains franchise details
    } catch (error) {
        console.error("Failed to create franchise:", error.response?.data || error.message);
        throw error;
    }
};

export const getFranchises = async () => {
    try {
        const response = await API.get("/dashboard");
        return response.data; // Assuming response contains an array of franchises
    } catch (error) {
        console.error("Failed to fetch franchises:", error.response?.data || error.message);
        throw error;
    }
};

export const deleteFranchise = async (id) => {
    try {
        const response = await API.delete(`/franchises/${id}`);
        return response.data; // Assuming response contains a success message
    } catch (error) {
        console.error("Failed to delete franchise:", error.response?.data || error.message);
        throw error;
    }
};

// User APIs
export const createUser = async (data) => {
    try {
        const response = await API.post("/users", data);
        return response.data; // Assuming response contains user details
    } catch (error) {
        console.error("Failed to create user:", error.response?.data || error.message);
        throw error;
    }
};

export const updateExamData = async (franchiseId, data) => {
    try {
        const response = await API.put(`/franchises/${franchiseId}/exam-data`, data);
        return response.data; // Assuming response contains updated franchise details
    } catch (error) {
        console.error("Failed to update exam data:", error.response?.data || error.message);
        throw error;
    }
};
